def dailymotion_download(url, output_dir='.', merge=True, info_only=False, **kwargs):
    html = get_content(rebuilt_url(url))
    info = json.loads(match1(html, 'qualities":({.+?}),"'))
    title = match1(html, '"video_title"\\s*:\\s*"([^"]+)"') or match1(html, '"title"\\s*:\\s*"([^"]+)"')
    title = unicodize(title)
    for quality in ['1080', '720', '480', '380', '240', '144', 'auto']:
        try:
            real_url = info[quality][1]['url']
            if real_url:
                break
        except KeyError:
            pass
    mime, ext, size = url_info(real_url)
    print_info(site_info, title, mime, size)
    if not info_only:
        download_urls([real_url], title, ext, size, output_dir=output_dir, merge=merge)

def sina_download(url, output_dir='.', merge=True, info_only=False, **kwargs):
    if 'news.sina.com.cn/zxt' in url:
        sina_zxt(url, output_dir=output_dir, merge=merge, info_only=info_only, **kwargs)
        return
    vid = match1(url, 'vid=(\\d+)')
    if vid is None:
        video_page = get_content(url)
        vid = hd_vid = match1(video_page, "hd_vid\\s*:\\s*\\'([^\\']+)\\'")
        if hd_vid == '0':
            vids = match1(video_page, "[^\\w]vid\\s*:\\s*\\'([^\\']+)\\'").split('|')
            vid = vids[-1]
    if vid is None:
        vid = match1(video_page, 'vid:"?(\\d+)"?')
    if vid:
        sina_download_by_vid(vid, output_dir=output_dir, merge=merge, info_only=info_only)
    else:
        vkey = match1(video_page, 'vkey\\s*:\\s*"([^"]+)"')
        if vkey is None:
            vid = match1(url, '#(\\d+)')
            sina_download_by_vid(vid, output_dir=output_dir, merge=merge, info_only=info_only)
            return
        title = match1(video_page, 'title\\s*:\\s*"([^"]+)"')
        sina_download_by_vkey(vkey, title=title, output_dir=output_dir, merge=merge, info_only=info_only)

def get_vid_from_url(self, url):
    hit = re.search('live.qq.com/(\\d+)', url)
    if hit is not None:
        return hit.group(1)
    hit = re.search('live.qq.com/directory/match/(\\d+)', url)
    if hit is not None:
        return self.get_room_id_from_url(hit.group(1))
    html = get_content(url)
    room_id = match1(html, 'room_id\\":(\\d+)')
    if room_id is None:
        log.wtf('Unknown page {}'.format(url))
    return room_id

