        wb_mp = re.search('<script src=([\\\'"])(.+?wb_mp\\.js)\\1>', mobile_page).group(2)
        return miaopai_download_by_wbmp(wb_mp, fid, output_dir=output_dir, merge=merge, info_only=info_only, total_size=None, **kwargs)
