def closest_ds_partition(table, ds, before=True, schema='default', metastore_conn_id='metastore_default'):
    from airflow.hooks.hive_hooks import HiveMetastoreHook
    if '.' in table:
        schema, table = table.split('.')
    hh = HiveMetastoreHook(metastore_conn_id=metastore_conn_id)
    partitions = hh.get_partitions(schema=schema, table_name=table)
    if not partitions:
        return None
    part_vals = [list(p.values())[0] for p in partitions]
    if ds in part_vals:
        return ds
    else:
        parts = [datetime.datetime.strptime(pv, '%Y-%m-%d') for pv in part_vals]
        target_dt = datetime.datetime.strptime(ds, '%Y-%m-%d')
        closest_ds = _closest_date(target_dt, parts, before_target=before)
        return closest_ds.isoformat()

def _wait_for_operation_to_complete(self, project_id, operation_name):
    service = self.get_conn()
    while True:
        operation_response = service.operations().get(project=project_id, operation=operation_name).execute(num_retries=self.num_retries)
        if operation_response.get('status') == CloudSqlOperationStatus.DONE:
            error = operation_response.get('error')
            if error:
                error_msg = str(error.get('errors'))[1:-1]
                raise AirflowException(error_msg)
            return
        time.sleep(TIME_TO_SLEEP_IN_SECONDS)

def get_proxy_version(self):
    self._download_sql_proxy_if_needed()
    command_to_run = [self.sql_proxy_path]
    command_to_run.extend(['--version'])
    command_to_run.extend(self._get_credential_parameters())
    result = subprocess.check_output(command_to_run).decode('utf-8')
    pattern = re.compile('^.*[V|v]ersion ([^;]*);.*$')
    m = pattern.match(result)
    if m:
        return m.group(1)
    else:
        return None

def delete_connection(self, session=None):
    self.log.info('Deleting connection %s', self.db_conn_id)
    connections = session.query(Connection).filter(Connection.conn_id == self.db_conn_id)
    if connections.count():
        connection = connections[0]
        session.delete(connection)
        session.commit()
    else:
        self.log.info('Connection was already deleted!')

def _get_error_code(self, e):
    try:
        matches = self.error_code_pattern.match(str(e))
        code = int(matches.group(0))
        return code
    except ValueError:
        return e

def mkdirs(path, mode):
    try:
        o_umask = os.umask(0)
        os.makedirs(path, mode)
    except OSError:
        if not os.path.isdir(path):
            raise
    finally:
        os.umask(o_umask)

def get_pandas_df(self, hql, parameters=None):
    import pandas
    cursor = self.get_cursor()
    try:
        cursor.execute(self._strip_sql(hql), parameters)
        data = cursor.fetchall()
    except DatabaseError as e:
        raise PrestoException(self._get_pretty_exception_message(e))
    column_descriptions = cursor.description
    if data:
        df = pandas.DataFrame(data)
        df.columns = [c[0] for c in column_descriptions]
    else:
        df = pandas.DataFrame()
    return df

def does_collection_exist(self, collection_name, database_name=None):
    if collection_name is None:
        raise AirflowBadRequest('Collection name cannot be None.')
    existing_container = list(self.get_conn().QueryContainers(get_database_link(self.__get_database_name(database_name)), {'query': 'SELECT * FROM r WHERE r.id=@id', 'parameters': [{'name': '@id', 'value': collection_name}]}))
    if len(existing_container) == 0:
        return False
    return True

def create_collection(self, collection_name, database_name=None):
    if collection_name is None:
        raise AirflowBadRequest('Collection name cannot be None.')
    existing_container = list(self.get_conn().QueryContainers(get_database_link(self.__get_database_name(database_name)), {'query': 'SELECT * FROM r WHERE r.id=@id', 'parameters': [{'name': '@id', 'value': collection_name}]}))
    if len(existing_container) == 0:
        self.get_conn().CreateContainer(get_database_link(self.__get_database_name(database_name)), {'id': collection_name})

def harvest_simple_dags(self):
    self._sync_metadata()
    self._heartbeat_manager()
    simple_dags = []
    if sys.platform == 'darwin':
        qsize = self._result_count
    else:
        qsize = self._result_queue.qsize()
    for _ in range(qsize):
        simple_dags.append(self._result_queue.get())
    self._result_count = 0
    return simple_dags

def end(self):
    if not self._process:
        self.log.warn('Ending without manager process.')
        return
    this_process = psutil.Process(os.getpid())
    try:
        manager_process = psutil.Process(self._process.pid)
    except psutil.NoSuchProcess:
        self.log.info('Manager process not running.')
        return
    if manager_process.is_running() and manager_process.pid in [x.pid for x in this_process.children()]:
        self.log.info('Terminating manager process: %s', manager_process.pid)
        manager_process.terminate()
        timeout = 5
        self.log.info('Waiting up to %ss for manager process to exit...', timeout)
        try:
            psutil.wait_procs({manager_process}, timeout)
        except psutil.TimeoutExpired:
            self.log.debug('Ran out of time while waiting for processes to exit')
    if manager_process.is_running() and manager_process.pid in [x.pid for x in this_process.children()]:
        self.log.info('Killing manager process: %s', manager_process.pid)
        manager_process.kill()
        manager_process.wait()

def end(self):
    pids_to_kill = self.get_all_pids()
    if len(pids_to_kill) > 0:
        this_process = psutil.Process(os.getpid())
        child_processes = [x for x in this_process.children(recursive=True) if x.is_running() and x.pid in pids_to_kill]
        for child in child_processes:
            self.log.info('Terminating child PID: %s', child.pid)
            child.terminate()
        timeout = 5
        self.log.info('Waiting up to %s seconds for processes to exit...', timeout)
        try:
            psutil.wait_procs(child_processes, timeout=timeout, callback=lambda x: self.log.info('Terminated PID %s', x.pid))
        except psutil.TimeoutExpired:
            self.log.debug('Ran out of time while waiting for processes to exit')
        child_processes = [x for x in this_process.children(recursive=True) if x.is_running() and x.pid in pids_to_kill]
        if len(child_processes) > 0:
            self.log.info('SIGKILL processes that did not terminate gracefully')
            for child in child_processes:
                self.log.info('Killing child PID: %s', child.pid)
                child.kill()
                child.wait()

def wait_for_transfer_job(self, job, expected_statuses=(GcpTransferOperationStatus.SUCCESS,), timeout=60):
    while timeout > 0:
        operations = self.list_transfer_operations(filter={FILTER_PROJECT_ID: job[PROJECT_ID], FILTER_JOB_NAMES: [job[NAME]]})
        if GCPTransferServiceHook.operations_contain_expected_statuses(operations, expected_statuses):
            return
        time.sleep(TIME_TO_SLEEP_IN_SECONDS)
        timeout -= TIME_TO_SLEEP_IN_SECONDS
    raise AirflowException('Timeout. The operation could not be completed within the allotted time.')

def operations_contain_expected_statuses(operations, expected_statuses):
    expected_statuses = {expected_statuses} if isinstance(expected_statuses, six.string_types) else set(expected_statuses)
    if len(operations) == 0:
        return False
    current_statuses = {operation[METADATA][STATUS] for operation in operations}
    if len(current_statuses - set(expected_statuses)) != len(current_statuses):
        return True
    if len(NEGATIVE_STATUSES - current_statuses) != len(NEGATIVE_STATUSES):
        raise AirflowException('An unexpected operation status was encountered. Expected: {}'.format(', '.join(expected_statuses)))
    return False

def run_command(command):
    process = subprocess.Popen(shlex.split(command), stdout=subprocess.PIPE, stderr=subprocess.PIPE, close_fds=True)
    output, stderr = [stream.decode(sys.getdefaultencoding(), 'ignore') for stream in process.communicate()]
    if process.returncode != 0:
        raise AirflowConfigException('Cannot execute {}. Error code is: {}. Output: {}, Stderr: {}'.format(command, process.returncode, output, stderr))
    return output

def get_template_field(env, fullname):
    modname, classname = fullname.rsplit('.', 1)
    try:
        with mock(env.config.autodoc_mock_imports):
            mod = import_module(modname)
    except ImportError:
        raise RoleException('Error loading %s module.' % (modname,))
    clazz = getattr(mod, classname)
    if not clazz:
        raise RoleException('Error finding %s class in %s module.' % (classname, modname))
    template_fields = getattr(clazz, 'template_fields')
    if not template_fields:
        raise RoleException('Could not find the template fields for %s class in %s module.' % (classname, modname))
    return list(template_fields)

def template_field_role(app, typ, rawtext, text, lineno, inliner, options={}, content=[]):
    text = utils.unescape(text)
    try:
        template_fields = get_template_field(app.env, text)
    except RoleException as e:
        msg = inliner.reporter.error('invalid class name %s \n%s' % (text, e), line=lineno)
        prb = inliner.problematic(rawtext, rawtext, msg)
        return ([prb], [msg])
    node = nodes.inline(rawtext=rawtext)
    for i, field in enumerate(template_fields):
        if i != 0:
            node += nodes.Text(', ')
        node += nodes.literal(field, '', nodes.Text(field))
    return ([node], [])

def chunks(items, chunk_size):
    if chunk_size <= 0:
        raise ValueError('Chunk size must be a positive integer')
    for i in range(0, len(items), chunk_size):
        yield items[i:i + chunk_size]

def reduce_in_chunks(fn, iterable, initializer, chunk_size=0):
    if len(iterable) == 0:
        return initializer
    if chunk_size == 0:
        chunk_size = len(iterable)
    return reduce(fn, chunks(iterable, chunk_size), initializer)
